    // 卓越(追加確率)でのみ発動し、成功時に攻撃%上昇と飛翔を得る。rateTableに卓越発動率を、
    // trTableに攻撃%上昇(発動成功時の値)を、soarValueTableに飛翔値(TR別)を登録する。
    rateTable: { base:40, TR1:40, TR2:50, TR3:60, TR4:80, TR5:100 }, // 卓越追加確率(%)
    trTable: { base:400, TR1:510, TR2:510, TR3:880, TR4:1280, TR5:1280 }, // 攻撃%上昇(発動成功時)
